export function initialize(wrapperElement, dotNetRef, timeoutMs) {
    let timer = null;
    let isIdle = false;

    function resetTimer() {
        if (isIdle) {
            isIdle = false;
            dotNetRef.invokeMethodAsync("OnUserActive");
        }
        clearTimeout(timer);
        timer = setTimeout(() => {
            isIdle = true;
            dotNetRef.invokeMethodAsync("OnUserIdle");
        }, timeoutMs);
    }

    const events = ["mousemove", "keydown", "click", "scroll", "touchstart"];
    events.forEach(e => wrapperElement.addEventListener(e, resetTimer, { passive: true }));

    resetTimer();

    return {
        dispose() {
            clearTimeout(timer);
            events.forEach(e => wrapperElement.removeEventListener(e, resetTimer));
        }
    };
}

